import {assess,validateInput,hash,sign} from './rules.mjs';
import {config,html,client,css} from './assets.mjs';
const json=(x,status=200)=>new Response(JSON.stringify(x),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
function user(r){const id=r.headers.get('oai-authenticated-user-id');if(!id)throw Object.assign(Error('Sign in to use the provider workspace.'),{status:401});return id;}
async function customer(r,e){if(r.headers.has('authorization')){const given=r.headers.get('authorization');if(!e.PARTNER_KEY||given!=='Bearer '+e.PARTNER_KEY)throw Object.assign(Error('Service credential rejected.'),{status:401});return 'saha-demo';}return 'browser:'+user(r);}
function sameOrigin(r){if(r.headers.get('origin')&&r.headers.get('origin')!==new URL(r.url).origin||r.headers.get('sec-fetch-site')==='cross-site')throw Object.assign(Error('Cross-origin browser writes are refused.'),{status:403});}
async function body(r){if(!r.headers.get('content-type')?.startsWith('application/json'))throw Object.assign(Error('Use JSON.'),{status:415});if(Number(r.headers.get('content-length')||0)>12000)throw Object.assign(Error('Request too large.'),{status:413});const reader=r.body?.getReader();if(!reader)throw Error('Missing request.');let n=0,parts=[];for(;;){const x=await reader.read();if(x.done)break;n+=x.value.length;if(n>12000){await reader.cancel();throw Object.assign(Error('Request too large.'),{status:413});}parts.push(x.value);}const bytes=new Uint8Array(n);let p=0;for(const x of parts){bytes.set(x,p);p+=x.length;}return JSON.parse(new TextDecoder('utf8',{fatal:true}).decode(bytes));}
export default {async fetch(r,e){try{
 const p=new URL(r.url).pathname;
 if(p==='/health')return json({appId:config.id,status:'ok',clinicalUse:false});
 if(p==='/api/manifest')return json({...config,schemaVersion:'frontline.v1',clinicalUse:false,modelExecution:'device; client-reported provenance',receiptAttestation:'provider validated inputs and applied explicit rules; does not attest client model execution',retention:'No image or audio storage. Synthetic result receipts retained for demonstration.',agreement:'SYNTHETIC-DEMO-v1'});
 if(p==='/api/openapi.json')return json({openapi:'3.1.0',info:{title:config.name,version:'frontline.v1'},paths:{'/api/assess':{post:{summary:'Assess confirmed synthetic observations',security:[{bearer:[]}],responses:{200:{description:'Signed review-required receipt'},202:{description:'Reserved; lookup only'},409:{description:'Key reused with different input'}}}},'/api/receipts/{id}':{get:{summary:'Read same-customer receipt; never reruns assessment',responses:{200:{description:'Stored signed receipt'},202:{description:'Outcome unresolved'},404:{description:'Not found'}}}}},components:{securitySchemes:{bearer:{type:'http',scheme:'bearer'}}}});
 if(p==='/api/ledger'){user(r);if(!e.DB)return json({error:'Provider storage unavailable'},503);const rows=await e.DB.prepare('SELECT id,customer,status,created FROM receipts ORDER BY created DESC LIMIT 50').all();return json({rows:rows.results});}
 if(p.startsWith('/api/receipts/')){const who=await customer(r,e),id=decodeURIComponent(p.slice('/api/receipts/'.length));const row=await e.DB.prepare('SELECT * FROM receipts WHERE id=? AND customer=?').bind(id,who).first();if(!row)return json({error:'Receipt not found.'},404);return row.result?json(JSON.parse(row.result)):json({requestId:id,status:'uncertain',message:'No result confirmed. Lookup only; do not resend.'},202);}
 if(p==='/api/assess'&&r.method==='POST'){
 if(!r.headers.has('authorization'))sameOrigin(r);const who=await customer(r,e);if(!e.DB||!e.PARTNER_KEY)return json({error:'Provider service is not configured.'},503);
 let input;try{input=validateInput(config,await body(r));}catch(err){return json({error:err.message},err.status||422);}
 if(r.headers.get('idempotency-key')!==input.requestId)return json({error:'Request and idempotency key must match.'},422);
 const digest=await hash(input),old=await e.DB.prepare('SELECT * FROM receipts WHERE id=?').bind(input.requestId).first();
 if(old){if(old.customer!==who||old.hash!==digest)return json({error:'Request key belongs to different input.'},409);return old.result?json(JSON.parse(old.result)):json({requestId:input.requestId,status:'uncertain'},202);}
 const created=new Date().toISOString(),claimed=await e.DB.prepare('INSERT OR IGNORE INTO receipts(id,customer,hash,status,created) VALUES(?,?,?,?,?)').bind(input.requestId,who,digest,'reserved',created).run();
 if(!claimed.meta.changes)return json({requestId:input.requestId,status:'uncertain'},202);
 const unsigned={schemaVersion:'frontline.v1',appId:config.id,requestId:input.requestId,customer:who,inputHash:digest,createdAt:created,providerOrganisation:config.organisation,model:config.model,modelRole:config.modelRole,evidenceKind:input.evidence.kind,inferenceProvenance:input.evidence.kind==='asr'||input.evidence.kind==='ocr'?'client-reported; not server-verified':'no AI inference claimed',fields:input.fields,evidenceText:input.evidence.text,...assess(config,input.fields)};
 const result={...unsigned,signature:await sign(unsigned,e.PARTNER_KEY)};
 await e.DB.prepare('UPDATE receipts SET status=?,result=? WHERE id=? AND customer=? AND hash=?').bind('completed',JSON.stringify(result),input.requestId,who,digest).run();return json(result);
 }
 if(p==='/app.js')return new Response(client,{headers:{'Content-Type':'text/javascript','Cache-Control':'no-cache'}});
 if(p==='/style.css')return new Response(css,{headers:{'Content-Type':'text/css'}});
 if(p==='/'||p==='/partners'){user(r);return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'self'; script-src 'self' https://cdn.jsdelivr.net 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src 'self' blob:; connect-src 'self' https://huggingface.co https://*.huggingface.co https://*.hf.co https://cdn.jsdelivr.net https://tessdata.projectnaptha.com; worker-src 'self' blob: https://cdn.jsdelivr.net; frame-ancestors 'self'; base-uri 'none'; object-src 'none'"}});}
 return json({error:'Not found'},404);
 }catch(err){return json({error:err.status?err.message:'Provider storage or processing unavailable. Keep the request key and check its receipt.'},err.status||503);}}};
